import type { AnalysisResponse } from "../types/contracts";
import { isRecord } from "./guards";
import { assetUrl } from "./trendMaps";

/** Precomputed places from public/regions/ (generated by `uv run python -m pipeline regions`). */
export type PlaceSummary = {
  id: string;
  name: string;
  group: "chihuahua" | "world";
  bbox: [number, number, number, number];
  file: string;
};

export type PlaceManifest = { version: 1; generated_at: string; regions: PlaceSummary[] };

export type PlaceFile = {
  id: string;
  name: string;
  bbox: [number, number, number, number];
  period: [string, string];
  variables: Record<string, AnalysisResponse>;
};

const DIR = "regions";

export async function loadPlaceManifest(baseUrl = import.meta.env.BASE_URL): Promise<PlaceManifest> {
  const response = await fetch(assetUrl(`${DIR}/manifest.json`, baseUrl));
  if (!response.ok) {
    throw new Error(`Could not load the list of places (${response.status})`);
  }
  const value: unknown = await response.json();
  if (!isRecord(value) || value.version !== 1 || !Array.isArray(value.regions)) {
    throw new Error("Invalid place manifest: expected version 1 with a regions list");
  }
  return value as PlaceManifest;
}

export async function loadPlace(file: string, baseUrl = import.meta.env.BASE_URL): Promise<PlaceFile> {
  const response = await fetch(assetUrl(`${DIR}/${file}`, baseUrl));
  if (!response.ok) {
    throw new Error(`Could not load this place (${response.status})`);
  }
  const value: unknown = await response.json();
  if (!isRecord(value) || !isRecord(value.variables)) {
    throw new Error("Invalid place file: expected a variables map");
  }
  return value as PlaceFile;
}
